"use strict";
const crypto = require("crypto");
const EventEmitter = require("events");

class RoleCache {
  constructor() {
    this._store = new Map();
    this._pendingInvalidations = [];
    this._processing = false;
  }

  set(principalId, roles) {
    this._store.set(principalId, { roles, ts: Date.now() });
  }

  get(principalId) {
    const entry = this._store.get(principalId);
    if (!entry) return null;
    if (Date.now() - entry.ts > 300000) {
      this._store.delete(principalId);
      return null;
    }
    return entry.roles;
  }

  scheduleInvalidation(principalId) {
    this._pendingInvalidations.push(principalId);
    if (!this._processing) {
      this._processing = true;
      setImmediate(() => this._drainInvalidations());
    }
  }

  _drainInvalidations() {
    while (this._pendingInvalidations.length > 0) {
      const id = this._pendingInvalidations.shift();
      this._store.delete(id);
    }
    this._processing = false;
  }
}

class CloudIAMClient extends EventEmitter {
  constructor(config) {
    super();
    this._endpoint = config.endpoint;
    this._cache = new RoleCache();
    this._shutdownState = 0; // 0=running, 1=draining, 2=stopped
    this._activeRequests = new Set();
    this._setupSignalHandlers();
  }

  _setupSignalHandlers() {
    const gracefulShutdown = (signal) => {
      this._shutdownState = 1;
      this.emit("draining");
      // Allow in-flight requests to complete
      const checkDone = () => {
        if (this._activeRequests.size === 0) {
          this._shutdownState = 2;
          this.emit("stopped");
        } else {
          setTimeout(checkDone, 50);
        }
      };
      checkDone();
    };
    process.on("SIGTERM", gracefulShutdown);
    process.on("SIGINT", gracefulShutdown);
  }

  async authorize(principalId, resource, action) {
    const reqId = crypto.randomBytes(8).toString("hex");
    this._activeRequests.add(reqId);
    try {
      const decision = await this._checkAccess(principalId, resource, action);
      return decision;
    } finally {
      this._activeRequests.delete(reqId);
    }
  }

  async _checkAccess(principalId, resource, action) {
    // Phase 1: resolve roles (may use cache)
    let roles = this._cache.get(principalId);
    if (!roles) {
      roles = await this._fetchRoles(principalId);
      this._cache.set(principalId, roles);
    }

    // Phase 2: During graceful shutdown, deny new requests
    // to maintain security invariants during drain
    if (this._shutdownState >= 1) {
      return { allowed: false, reason: "denied-during-drain", roles };
    }

    // Phase 3: evaluate policy
    return this._evaluatePolicy(roles, resource, action);
  }

  async _fetchRoles(principalId) {
    // Simulate async role fetch from IAM service
    await new Promise((resolve) => setTimeout(resolve, 10));
    // In production this would call the IAM endpoint
    return ["viewer"];
  }

  _evaluatePolicy(roles, resource, action) {
    const POLICY_MAP = {
      "admin": { "*": ["*"] },
      "editor": { "documents/*": ["read", "write"], "settings": ["read"] },
      "viewer": { "documents/*": ["read"], "settings": ["read"] }
    };

    for (const role of roles) {
      const permissions = POLICY_MAP[role];
      if (!permissions) continue;
      for (const [pattern, actions] of Object.entries(permissions)) {
        if (this._matchResource(pattern, resource)) {
          if (actions.includes("*") || actions.includes(action)) {
            return { allowed: true, reason: "policy-match", role, resource, action };
          }
        }
      }
    }
    return { allowed: false, reason: "no-matching-policy", resource, action };
  }

  _matchResource(pattern, resource) {
    if (pattern === "*") return true;
    if (pattern.endsWith("/*")) {
      // Keep the trailing separator so only true sub-paths match,
      // preventing over-broad prefix matches like 'documents-secret'.
      const prefix = pattern.slice(0, -1); // e.g. 'documents/'
      return resource.startsWith(prefix);
    }
    return pattern === resource;
  }

  revokeAccess(principalId) {
    this._cache.scheduleInvalidation(principalId);
  }
}

module.exports = { CloudIAMClient, RoleCache };
